/**
 * Extracts interactive follow-up suggestions generated by InfraBot from the assistant's message content.
 * Expected format from system prompt:
 * <!-- FOLLOW_UP_SUGGESTIONS: ["Saran 1", "Saran 2", "Saran 3"] -->
 */
export function extractFollowUpSuggestions(content: string): {
  cleanContent: string;
  suggestions: string[];
} {
  if (!content) {
    return { cleanContent: '', suggestions: [] };
  }

  const suggestionRegex = /<!--\s*FOLLOW_UP_SUGGESTIONS:\s*(\[[\s\S]*?\])\s*-->/i;
  const match = content.match(suggestionRegex);

  if (!match) {
    return { cleanContent: content, suggestions: [] };
  }

  const cleanContent = content.replace(suggestionRegex, '').trim();
  let suggestions: string[] = [];

  try {
    const parsed = JSON.parse(match[1]);
    if (Array.isArray(parsed)) {
      suggestions = parsed
        .filter((item): item is string => typeof item === 'string' && item.trim().length > 0)
        .map((item) => item.trim());
    }
  } catch {
    // If parsing fails, fall back to empty suggestions array
    suggestions = [];
  }

  return { cleanContent, suggestions };
}

